-- Run in Supabase SQL Editor, in order 001 -> 002 -> 003 -> 004
create extension if not exists pgcrypto;
create table if not exists public.allowed_users(user_id uuid primary key references auth.users(id) on delete cascade, email text not null unique, created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, category text not null default 'General', description text, unit text not null default 'bag', selling_price numeric(12,2) not null default 0, min_stock numeric(12,3) not null default 0, notes text, image_url text, image_path text, created_at timestamptz default now());
create table if not exists public.purchase_batches(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, qty_purchased numeric(12,3) not null check(qty_purchased>0), qty_remaining numeric(12,3) not null check(qty_remaining>=0), purchase_date date not null, arrival_date date not null, total_cost numeric(12,2) not null check(total_cost>=0), cost_per_unit numeric(12,4) generated always as (case when qty_purchased>0 then total_cost/qty_purchased else 0 end) stored, supplier text, notes text, sold_out_at timestamptz, created_at timestamptz default now());
create table if not exists public.sales(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, qty numeric(12,3) not null check(qty>0), sale_date date not null, unit_price numeric(12,2) not null, total_revenue numeric(12,2) generated always as (qty*unit_price) stored, notes text, created_at timestamptz default now());
create table if not exists public.sale_allocations(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, sale_id uuid not null references public.sales(id) on delete cascade, batch_id uuid not null references public.purchase_batches(id) on delete cascade, qty numeric(12,3) not null, cost_per_unit numeric(12,4) not null, cogs numeric(12,2) generated always as (qty*cost_per_unit) stored);
create table if not exists public.stock_movements(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, type text not null, qty_delta numeric(12,3) not null, reference_type text, reference_id uuid, reason text, created_at timestamptz default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, description text not null, amount numeric(12,2) not null check(amount>=0), expense_date date not null, category text not null, notes text, created_at timestamptz default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, entity_type text not null, entity_id uuid, action text not null, old_values jsonb, new_values jsonb, created_at timestamptz default now());
create index if not exists idx_products_user on public.products(user_id);
create index if not exists idx_batches_product on public.purchase_batches(product_id, arrival_date);
create index if not exists idx_sales_product_date on public.sales(product_id, sale_date);
create index if not exists idx_expenses_date on public.expenses(user_id, expense_date);
